    private void migrateLegacyConfiguration()
    {
        migrateColumns();
        migrateHiddenButtons();
        migrateLayoutMode();
        migrateButtonScale();
        migrateDefaultColors();
        removeObsoleteInterfaceSettings();
    }

    private void removeObsoleteInterfaceSettings()
    {
        final String[] keys =
        {
            "scaleSidePanel",
            "sidePanelScale",
            "useGlobalUiScale",
            "globalUiMagnification",
            "keepSidePanelOpen",
            "restoreLastSidePanel",
            "lastSidePanelTab",
            "hideVanillaRail",
            "snapLinks",
            "columns",
            "hiddenTabs",
            "layoutStyle",
            "buttonSize"
        };

        for (String key : keys)
        {
            configManager.unsetConfiguration(
                CustomGameTabsConfig.GROUP,
                key
            );
        }
    }

    private void migrateColumns()
    {
        if (
            configManager.getConfiguration(
                CustomGameTabsConfig.GROUP,
                "buttonsAcross"
            ) != null
        )
        {
            return;
        }

        final String oldColumns =
            configManager.getConfiguration(
                CustomGameTabsConfig.GROUP,
                "columns"
            );

        if ("ONE".equalsIgnoreCase(oldColumns))
        {
            configManager.setConfiguration(
                CustomGameTabsConfig.GROUP,
                "buttonsAcross",
                1
            );
        }
        else if ("TWO".equalsIgnoreCase(oldColumns))
        {
            configManager.setConfiguration(
                CustomGameTabsConfig.GROUP,
                "buttonsAcross",
                2
            );
        }
        else if (
            oldColumns != null
                && oldColumns.matches("\\d+")
        )
        {
            configManager.setConfiguration(
                CustomGameTabsConfig.GROUP,
                "buttonsAcross",
                oldColumns
            );
        }
    }

    private void migrateHiddenButtons()
    {
        final String hidden =
            configManager.getConfiguration(
                CustomGameTabsConfig.GROUP,
                "hiddenTabs"
            );

        if (hidden == null || hidden.isBlank())
        {
            return;
        }

        for (int tabIndex : TabLayout.parse(hidden))
        {
            final String key = TabLayout.showKey(tabIndex);

            if (
                configManager.getConfiguration(
                    CustomGameTabsConfig.GROUP,
                    key
                ) == null
            )
            {
                configManager.setConfiguration(
                    CustomGameTabsConfig.GROUP,
                    key,
                    false
                );
            }
        }
    }

    private void migrateLayoutMode()
    {
        final String existingMode =
            configManager.getConfiguration(
                CustomGameTabsConfig.GROUP,
                "layoutMode"
            );

        if (existingMode == null)
        {
            final String separate =
                configManager.getConfiguration(
                    CustomGameTabsConfig.GROUP,
                    "moveSeparately"
                );
            final String oldMode =
                configManager.getConfiguration(
                    CustomGameTabsConfig.GROUP,
                    "layoutStyle"
                );

            final boolean freeform =
                "true".equalsIgnoreCase(separate)
                    || "MOVE_ONE_BY_ONE".equalsIgnoreCase(oldMode);

            configManager.setConfiguration(
                CustomGameTabsConfig.GROUP,
                "layoutMode",
                freeform
                    ? TabLayoutMode.FREEFORM.name()
                    : TabLayoutMode.DOCKED.name()
            );
        }

        configManager.unsetConfiguration(
            CustomGameTabsConfig.GROUP,
            "moveSeparately"
        );
    }

    private void migrateButtonScale()
    {
        final String raw =
            configManager.getConfiguration(
                CustomGameTabsConfig.GROUP,
                "buttonScale"
            );

        if (raw != null && raw.matches("\\d+"))
        {
            final int value = Math.max(
                25,
                Math.min(200, Integer.parseInt(raw))
            );

            if (!raw.equals(Integer.toString(value)))
            {
                configManager.setConfiguration(
                    CustomGameTabsConfig.GROUP,
                    "buttonScale",
                    value
                );
            }

            return;
        }

        if (raw != null && raw.matches("PERCENT_\\d+"))
        {
            final int value = Math.max(
                25,
                Math.min(
                    200,
                    Integer.parseInt(
                        raw.substring("PERCENT_".length())
                    )
                )
            );

            configManager.setConfiguration(
                CustomGameTabsConfig.GROUP,
                "buttonScale",
                value
            );
            return;
        }

        final String oldSize =
            configManager.getConfiguration(
                CustomGameTabsConfig.GROUP,
                "buttonSize"
            );

        int legacyPixels = 42;

        if (oldSize != null)
        {
            try
            {
                legacyPixels = Integer.parseInt(oldSize);
            }
            catch (NumberFormatException ignored)
            {
                legacyPixels = 42;
            }
        }

        final int estimatedPercent = Math.round(
            legacyPixels * 100.0f / 42.0f
        );

        configManager.setConfiguration(
            CustomGameTabsConfig.GROUP,
            "buttonScale",
            Math.max(25, Math.min(200, estimatedPercent))
        );
    }

    private void migrateDefaultColors()
    {
        migrateDefaultColor(
            "buttonColor",
            new java.awt.Color(41, 38, 32, 230),
            new java.awt.Color(49, 38, 26, 238)
        );
        migrateDefaultColor(
            "hoverColor",
            new java.awt.Color(75, 64, 45, 240),
            new java.awt.Color(82, 62, 36, 246)
        );
        migrateDefaultColor(
            "selectedColor",
            new java.awt.Color(97, 76, 39, 245),
            new java.awt.Color(112, 82, 35, 250)
        );
        migrateDefaultColor(
            "borderColor",
            new java.awt.Color(126, 100, 54, 240),
            new java.awt.Color(151, 113, 49, 248)
        );
    }

    private void migrateDefaultColor(
        String key,
        java.awt.Color oldDefault,
        java.awt.Color newDefault
    )
    {
        final java.awt.Color current =
            configManager.getConfiguration(
                CustomGameTabsConfig.GROUP,
                key,
                java.awt.Color.class
            );

        if (current != null && current.equals(oldDefault))
        {
            configManager.setConfiguration(
                CustomGameTabsConfig.GROUP,
                key,
                newDefault
            );
        }
    }
}

package com.freddy.customgametabs;

final class DockMetrics
{
    private static final double NORMAL_BUTTON_SIZE = 42.0;
    private static final double NORMAL_FRAME_PADDING = 3.0;
    private static final double NORMAL_CORNER_RADIUS = 6.0;
    private static final float NORMAL_BORDER_WIDTH = 1.2f;

    private DockMetrics()
    {
    }

    static double buttonSizeExact(CustomGameTabsConfig config)
    {
        return scaleExact(
            NORMAL_BUTTON_SIZE,
            config.buttonScale()
        );
    }

    static int buttonCellSize(CustomGameTabsConfig config)
    {
        return Math.max(
            1,
            (int) Math.ceil(buttonSizeExact(config))
        );
    }

    static int gap(CustomGameTabsConfig config)
    {
        return gapPixels(config.gap());
    }

    static int gapPixels(int configuredPixels)
    {
        return Math.max(0, configuredPixels);
    }

    static double framePaddingExact(CustomGameTabsConfig config)
    {
        return Math.max(
            1.0,
            scaleExact(
                NORMAL_FRAME_PADDING,
                config.buttonScale()
            )
        );
    }

    static double cornerRadiusExact(CustomGameTabsConfig config)
    {
        return Math.max(
            2.0,
            scaleExact(
                NORMAL_CORNER_RADIUS,
                config.buttonScale()
            )
        );
    }

    static float borderWidth(CustomGameTabsConfig config)
    {
        return Math.max(
            0.65f,
            NORMAL_BORDER_WIDTH
                * clampScale(config.buttonScale())
                / 100.0f
        );
    }

    static double scaleExact(double normalPixels, int percent)
    {
        return Math.max(
            0.01,
            normalPixels * clampScale(percent) / 100.0
        );
    }

    private static int clampScale(int percent)
    {
        return Math.max(25, Math.min(200, percent));
    }
}

