package com.freddy.customgametabs;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.geom.Rectangle2D;
import java.awt.geom.RoundRectangle2D;
import java.util.Arrays;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** Drawer handle plus its temporary row/column of drawer-only tabs. */
final class DrawerOverlay extends Overlay
{
    private static final Color HANDLE_FILL = new Color(49, 38, 26, 245);
    private static final Color ARROW_GOLD = new Color(219, 166, 67);
    private static final Color ARROW_OUTLINE = new Color(79, 54, 28);
    private static final long ANIMATION_NANOS = 170_000_000L;

    private final Client client;
    private final CustomGameTabsConfig config;
    private final TabIconRenderer iconRenderer;
    private final NativeTabController nativeTabController;
    private final TabTooltipPresenter tooltipPresenter;

    private final Rectangle2D.Double[] buttonBounds =
        new Rectangle2D.Double[LayoutSpec.TABS.length];
    private volatile Rectangle2D.Double handleBounds;
    private volatile boolean rendered;
    private volatile boolean expanded;
    private volatile double animationFrom;
    private volatile long animationStartNanos;
    private volatile DrawerDirection effectiveDirection = DrawerDirection.LEFT;
    private volatile int hoveredTab = -1;
    private volatile boolean hoveredHandle;

    @Inject
    DrawerOverlay(
        Client client,
        CustomGameTabsConfig config,
        TabIconRenderer iconRenderer,
        NativeTabController nativeTabController,
        TabTooltipPresenter tooltipPresenter
    )
    {
        this.client = client;
        this.config = config;
        this.iconRenderer = iconRenderer;
        this.nativeTabController = nativeTabController;
        this.tooltipPresenter = tooltipPresenter;

        setPosition(OverlayPosition.TOP_RIGHT);
        setLayer(OverlayLayer.MANUAL);
        drawAfterLayer(InterfaceID.ToplevelPreEoc.MAP_CONTAINER);
        /* Non-dynamic overlays with lower priority draw later. Keep drawer over CGT tabs. */
        setPriority(PRIORITY_HIGH);
        setSnappable(false);
        setDragTargetable(false);
        setMinimumSize(8);
    }

    @Override
    public String getName()
    {
        return "Custom Game Tabs Drawer";
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        final LayoutSpec layout = LayoutSpec.forRoot(client.getTopLevelInterfaceId());
        final List<Integer> drawerTabs = TabLayout.drawerOrder(config);

        if (client.getGameState() != GameState.LOGGED_IN
            || layout == null
            || !config.drawerEnabled()
            || drawerTabs.isEmpty())
        {
            clearBounds();
            return null;
        }

        rendered = false;
        Arrays.fill(buttonBounds, null);
        applyQualityHints(graphics);

        final int cell = DockMetrics.buttonCellSize(config);
        final double buttonSize = DockMetrics.buttonSizeExact(config);
        final int gap = DockMetrics.gap(config);
        final double radius = DockMetrics.cornerRadiusExact(config);
        final double animation = animationProgress();

        /* Keep the handle at one stable local offset whether open or closed.
         * CGT owns input/movement, so a full transparent layout rectangle cannot
         * accidentally become a native RuneLite drag surface. */
        final Point handleOffset = localHandleOffset(
            effectiveDirection,
            true,
            drawerTabs.size(),
            cell,
            gap
        );

        final int totalWidth = contentWidth(
            effectiveDirection,
            true,
            drawerTabs.size(),
            cell,
            gap
        );
        final int totalHeight = contentHeight(
            effectiveDirection,
            true,
            drawerTabs.size(),
            cell,
            gap
        );

        final Rectangle2D.Double localHandle = new Rectangle2D.Double(
            handleOffset.x,
            handleOffset.y,
            cell,
            cell
        );

        drawHandle(graphics, localHandle, radius);
        handleBounds = new Rectangle2D.Double(
            getBounds().x + localHandle.x,
            getBounds().y + localHandle.y,
            localHandle.width,
            localHandle.height
        );

        if (animation > 0.001)
        {
            for (int position = 0; position < drawerTabs.size(); position++)
            {
                final int tabIndex = drawerTabs.get(position);
                final Point tabOffset = drawerTabOffset(
                    effectiveDirection,
                    position,
                    drawerTabs.size(),
                    cell,
                    gap
                );
                final double animatedX = handleOffset.x
                    + (tabOffset.x - handleOffset.x) * animation;
                final double animatedY = handleOffset.y
                    + (tabOffset.y - handleOffset.y) * animation;
                final Rectangle2D.Double localBounds = new Rectangle2D.Double(
                    animatedX,
                    animatedY,
                    buttonSize,
                    buttonSize
                );

                buttonBounds[tabIndex] = new Rectangle2D.Double(
                    getBounds().x + localBounds.x,
                    getBounds().y + localBounds.y,
                    localBounds.width,
                    localBounds.height
                );

                final boolean selected = nativeTabController.isTabActive(tabIndex);
                final boolean hovered = hoveredTab == tabIndex;
                final int baseOpacity = selected
                    ? config.selectedOpacity()
                    : hovered ? config.hoverOpacity() : config.idleOpacity();
                final int opacity = (int) Math.round(baseOpacity * animation);

                drawButton(
                    graphics,
                    layout,
                    tabIndex,
                    localBounds,
                    selected,
                    hovered,
                    opacity,
                    radius
                );
            }
        }

        if (config.showTooltip() && hoveredTab >= 0)
        {
            tooltipPresenter.showIfAvailable(nativeTabController.getTabName(hoveredTab));
        }

        rendered = true;
        return new Dimension(Math.max(1, totalWidth), Math.max(1, totalHeight));
    }

    void setFreeformMovable(boolean movable)
    {
        /* CGT moves the handle itself. Keeping this non-movable prevents the
         * generic OverlayRenderer from treating transparent drawer bounds as an
         * Alt-drag target. */
        setMovable(false);
    }

    void setExpanded(boolean expanded)
    {
        final double current = animationProgress();
        final double target = expanded ? 1.0 : 0.0;
        if (this.expanded == expanded && Math.abs(current - target) < 0.001)
        {
            return;
        }

        animationFrom = current;
        this.expanded = expanded;
        animationStartNanos = System.nanoTime();
        revalidate();
    }

    boolean isExpanded()
    {
        return expanded;
    }

    void setEffectiveDirection(DrawerDirection direction)
    {
        effectiveDirection = direction == null || direction == DrawerDirection.AUTO
            ? DrawerDirection.LEFT
            : direction;
        revalidate();
    }

    DrawerDirection getEffectiveDirection()
    {
        return effectiveDirection;
    }

    int tabAt(int x, int y)
    {
        if (!rendered)
        {
            return -1;
        }
        for (int tab = 0; tab < buttonBounds.length; tab++)
        {
            final Rectangle2D bounds = buttonBounds[tab];
            if (bounds != null && bounds.contains(x, y))
            {
                return tab;
            }
        }
        return -1;
    }

    boolean handleContains(int x, int y)
    {
        final Rectangle2D bounds = handleBounds;
        return rendered && bounds != null && bounds.contains(x, y);
    }

    boolean containsInputSurface(int x, int y)
    {
        if (!rendered)
        {
            return false;
        }
        return handleContains(x, y) || tabAt(x, y) >= 0;
    }

    Point getHandleLocation()
    {
        final Rectangle2D bounds = handleBounds;
        if (rendered && bounds != null)
        {
            return new Point((int) Math.round(bounds.getX()), (int) Math.round(bounds.getY()));
        }

        final Point preferred = getPreferredLocation();
        if (preferred == null)
        {
            return null;
        }
        final List<Integer> drawerTabs = TabLayout.drawerOrder(config);
        final Point offset = localHandleOffset(
            effectiveDirection,
            true,
            drawerTabs.size(),
            DockMetrics.buttonCellSize(config),
            DockMetrics.gap(config)
        );
        return new Point(preferred.x + offset.x, preferred.y + offset.y);
    }

    Point topLeftForHandle(Point handleLocation)
    {
        final List<Integer> drawerTabs = TabLayout.drawerOrder(config);
        final Point offset = localHandleOffset(
            effectiveDirection,
            true,
            drawerTabs.size(),
            DockMetrics.buttonCellSize(config),
            DockMetrics.gap(config)
        );
        return new Point(handleLocation.x - offset.x, handleLocation.y - offset.y);
    }

    Dimension contentSize()
    {
        final List<Integer> drawerTabs = TabLayout.drawerOrder(config);
        final int cell = DockMetrics.buttonCellSize(config);
        final int gap = DockMetrics.gap(config);
        return new Dimension(
            contentWidth(effectiveDirection, true, drawerTabs.size(), cell, gap),
            contentHeight(effectiveDirection, true, drawerTabs.size(), cell, gap)
        );
    }

    void onMouseMoved(int x, int y)
    {
        hoveredTab = tabAt(x, y);
        hoveredHandle = handleContains(x, y);
    }

    void onMouseExited()
    {
        hoveredTab = -1;
        hoveredHandle = false;
    }

    private void drawHandle(Graphics2D graphics, Rectangle2D.Double bounds, double radius)
    {
        final float strokeWidth = DockMetrics.borderWidth(config);
        final double inset = strokeWidth / 2.0;
        final RoundRectangle2D.Double shape = new RoundRectangle2D.Double(
            bounds.x + inset,
            bounds.y + inset,
            Math.max(0.5, bounds.width - strokeWidth),
            Math.max(0.5, bounds.height - strokeWidth),
            radius,
            radius
        );

        final int opacity = hoveredHandle ? config.hoverOpacity() : Math.max(config.idleOpacity(), 70);
        graphics.setColor(withOpacity(hoveredHandle ? config.hoverColor() : HANDLE_FILL, opacity));
        graphics.fill(shape);
        graphics.setColor(withOpacity(config.borderColor(), opacity));
        graphics.setStroke(new BasicStroke(strokeWidth));
        graphics.draw(shape);

        final int cx = (int) Math.round(bounds.getCenterX());
        final int cy = (int) Math.round(bounds.getCenterY());
        final int arm = Math.max(3, (int) Math.round(bounds.width * 0.16));
        final DrawerDirection arrowDirection = expanded
            ? opposite(effectiveDirection)
            : effectiveDirection;
        final Polygon arrow = arrowPolygon(arrowDirection, cx, cy, arm);

        graphics.setColor(ARROW_OUTLINE);
        graphics.setStroke(new BasicStroke(Math.max(2f, strokeWidth + 1f)));
        graphics.drawPolygon(arrow);
        graphics.setColor(ARROW_GOLD);
        graphics.fillPolygon(arrow);
    }

    private void drawButton(
        Graphics2D graphics,
        LayoutSpec layout,
        int tabIndex,
        Rectangle2D.Double bounds,
        boolean selected,
        boolean hovered,
        int opacity,
        double radius
    )
    {
        final Color fill = selected
            ? config.selectedColor()
            : hovered ? config.hoverColor() : config.buttonColor();
        final float strokeWidth = DockMetrics.borderWidth(config);
        final double inset = strokeWidth / 2.0;
        final RoundRectangle2D.Double shape = new RoundRectangle2D.Double(
            bounds.x + inset,
            bounds.y + inset,
            Math.max(0.5, bounds.width - strokeWidth),
            Math.max(0.5, bounds.height - strokeWidth),
            radius,
            radius
        );

        graphics.setColor(withOpacity(fill, opacity));
        graphics.fill(shape);
        graphics.setColor(withOpacity(selected ? config.borderColor().brighter() : config.borderColor(), opacity));
        graphics.setStroke(new BasicStroke(strokeWidth));
        graphics.draw(shape);

        final Widget iconWidget = client.getWidget(layout.getIconId(tabIndex));
        iconRenderer.draw(
            graphics,
            iconWidget,
            LayoutSpec.TABS[tabIndex],
            shape.getBounds2D(),
            opacity
        );
    }

    private double animationProgress()
    {
        final double target = expanded ? 1.0 : 0.0;
        final long started = animationStartNanos;
        if (started == 0L)
        {
            return target;
        }

        final double elapsed = Math.max(0.0, System.nanoTime() - started);
        final double linear = Math.min(1.0, elapsed / ANIMATION_NANOS);
        if (linear >= 1.0)
        {
            return target;
        }

        /* Cubic ease-out: responsive at the click, gentle at the final slot. */
        final double eased = 1.0 - Math.pow(1.0 - linear, 3.0);
        return animationFrom + (target - animationFrom) * eased;
    }

    private static DrawerDirection opposite(DrawerDirection direction)
    {
        switch (direction)
        {
            case LEFT: return DrawerDirection.RIGHT;
            case RIGHT: return DrawerDirection.LEFT;
            case UP: return DrawerDirection.DOWN;
            case DOWN: return DrawerDirection.UP;
            default: return DrawerDirection.LEFT;
        }
    }

    private static Polygon arrowPolygon(DrawerDirection direction, int cx, int cy, int arm)
    {
        switch (direction)
        {
            case RIGHT:
                return new Polygon(
                    new int[] {cx - arm, cx - arm, cx + arm},
                    new int[] {cy - arm, cy + arm, cy},
                    3
                );
            case UP:
                return new Polygon(
                    new int[] {cx - arm, cx + arm, cx},
                    new int[] {cy + arm, cy + arm, cy - arm},
                    3
                );
            case DOWN:
                return new Polygon(
                    new int[] {cx - arm, cx + arm, cx},
                    new int[] {cy - arm, cy - arm, cy + arm},
                    3
                );
            case LEFT:
            default:
                return new Polygon(
                    new int[] {cx + arm, cx + arm, cx - arm},
                    new int[] {cy - arm, cy + arm, cy},
                    3
                );
        }
    }

    private static Point localHandleOffset(
        DrawerDirection direction,
        boolean expanded,
        int count,
        int cell,
        int gap
    )
    {
        if (!expanded || count <= 0)
        {
            return new Point(0, 0);
        }
        final int extent = count * (cell + gap);
        switch (direction)
        {
            case LEFT: return new Point(extent, 0);
            case UP: return new Point(0, extent);
            default: return new Point(0, 0);
        }
    }

    private static Point drawerTabOffset(
        DrawerDirection direction,
        int position,
        int count,
        int cell,
        int gap
    )
    {
        final int step = cell + gap;
        switch (direction)
        {
            case LEFT:
                return new Point((count - 1 - position) * step, 0);
            case RIGHT:
                return new Point((position + 1) * step, 0);
            case UP:
                return new Point(0, (count - 1 - position) * step);
            case DOWN:
            default:
                return new Point(0, (position + 1) * step);
        }
    }

    private static int contentWidth(
        DrawerDirection direction,
        boolean expanded,
        int count,
        int cell,
        int gap
    )
    {
        if (expanded && count > 0 && (direction == DrawerDirection.LEFT || direction == DrawerDirection.RIGHT))
        {
            return (count + 1) * cell + count * gap;
        }
        return cell;
    }

    private static int contentHeight(
        DrawerDirection direction,
        boolean expanded,
        int count,
        int cell,
        int gap
    )
    {
        if (expanded && count > 0 && (direction == DrawerDirection.UP || direction == DrawerDirection.DOWN))
        {
            return (count + 1) * cell + count * gap;
        }
        return cell;
    }

    private static void applyQualityHints(Graphics2D graphics)
    {
        graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        graphics.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
        graphics.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
        graphics.setRenderingHint(RenderingHints.KEY_ALPHA_INTERPOLATION, RenderingHints.VALUE_ALPHA_INTERPOLATION_QUALITY);
    }

    private static Color withOpacity(Color color, int percent)
    {
        final int alpha = Math.round(color.getAlpha() * Math.max(0, Math.min(100, percent)) / 100.0f);
        return new Color(color.getRed(), color.getGreen(), color.getBlue(), Math.max(0, Math.min(255, alpha)));
    }

    private void clearBounds()
    {
        rendered = false;
        handleBounds = null;
        Arrays.fill(buttonBounds, null);
        hoveredTab = -1;
        hoveredHandle = false;
    }
}

package com.freddy.customgametabs;

import java.awt.Rectangle;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

final class LayoutSpec
{
    static final int INVENTORY_TAB = 3;
    static final int LOGOUT_TAB = 10;

    static final TabDefinition[] TABS = new TabDefinition[]
    {
        new TabDefinition("Combat Options", "CB"),
        new TabDefinition("Skills", "SK"),
        new TabDefinition("Quest List", "Q"),
        new TabDefinition("Inventory", "I"),
        new TabDefinition("Worn Equipment", "EQ"),
        new TabDefinition("Prayer", "PR"),
        new TabDefinition("Magic", "MG"),
        new TabDefinition("Friends Chat", "FC"),
        new TabDefinition("Ignore List", "IG"),
        new TabDefinition("Friends List", "FR"),
        new TabDefinition("Logout", "X"),
        new TabDefinition("Options", "OP"),
        new TabDefinition("Emotes", "EM"),
        new TabDefinition("Music Player", "MU")
    };

    static final LayoutSpec MODERN = new LayoutSpec(
        InterfaceID.TOPLEVEL_PRE_EOC,
        InterfaceID.ToplevelPreEoc.SIDE_BACKGROUND,
        InterfaceID.ToplevelPreEoc.SIDE_CONTAINER,
        new int[]
        {
            InterfaceID.ToplevelPreEoc.SIDE_STATIC_LAYER,
            InterfaceID.ToplevelPreEoc.SIDE_MOVABLE_LAYER
        },
        new int[]
        {
            InterfaceID.ToplevelPreEoc.SIDE_STATIC_BACKGROUND,
            InterfaceID.ToplevelPreEoc.SIDE_MOVABLE_BACKGROUND
        },
        new int[]
        {
            InterfaceID.ToplevelPreEoc.STONE0,
            InterfaceID.ToplevelPreEoc.STONE1,
            InterfaceID.ToplevelPreEoc.STONE2,
            InterfaceID.ToplevelPreEoc.STONE3,
            InterfaceID.ToplevelPreEoc.STONE4,
            InterfaceID.ToplevelPreEoc.STONE5,
            InterfaceID.ToplevelPreEoc.STONE6,
            InterfaceID.ToplevelPreEoc.STONE7,
            InterfaceID.ToplevelPreEoc.STONE8,
            InterfaceID.ToplevelPreEoc.STONE9,
            InterfaceID.ToplevelPreEoc.STONE10,
            InterfaceID.ToplevelPreEoc.STONE11,
            InterfaceID.ToplevelPreEoc.STONE12,
            InterfaceID.ToplevelPreEoc.STONE13
        },
        new int[]
        {
            InterfaceID.ToplevelPreEoc.ICON0,
            InterfaceID.ToplevelPreEoc.ICON1,
            InterfaceID.ToplevelPreEoc.ICON2,
            InterfaceID.ToplevelPreEoc.ICON3,
            InterfaceID.ToplevelPreEoc.ICON4,
            InterfaceID.ToplevelPreEoc.ICON5,
            InterfaceID.ToplevelPreEoc.ICON6,
            InterfaceID.ToplevelPreEoc.ICON7,
            InterfaceID.ToplevelPreEoc.ICON8,
            InterfaceID.ToplevelPreEoc.ICON9,
            InterfaceID.ToplevelPreEoc.ICON10,
            InterfaceID.ToplevelPreEoc.ICON11,
            InterfaceID.ToplevelPreEoc.ICON12,
            InterfaceID.ToplevelPreEoc.ICON13
        }
    );

    private final int rootId;
    private final int sideBackgroundId;
    private final int sideContainerId;
    private final int[] railLayerIds;
    private final int[] backgroundIds;
    private final int[] stoneIds;
    private final int[] iconIds;

    private LayoutSpec(
        int rootId,
        int sideBackgroundId,
        int sideContainerId,
        int[] railLayerIds,
        int[] backgroundIds,
        int[] stoneIds,
        int[] iconIds
    )
    {
        this.rootId = rootId;
        this.sideBackgroundId = sideBackgroundId;
        this.sideContainerId = sideContainerId;
        this.railLayerIds = railLayerIds;
        this.backgroundIds = backgroundIds;
        this.stoneIds = stoneIds;
        this.iconIds = iconIds;
    }

    int[] getRailLayerIds()
    {
        return railLayerIds;
    }

    int[] getBackgroundIds()
    {
        return backgroundIds;
    }

    int getStoneId(int tabIndex)
    {
        return stoneIds[tabIndex];
    }

    int getIconId(int tabIndex)
    {
        return iconIds[tabIndex];
    }

    boolean isSidePanelOpen(Client client)
    {
        return visibleBounds(client.getWidget(sideContainerId)) != null
            || visibleBounds(client.getWidget(sideBackgroundId)) != null;
    }

    /**
     * Capture the native side-panel rectangles on the RuneLite client thread.
     * Callers may safely publish/read the returned immutable Rectangle copies
     * from AWT mouse callbacks without touching Widget state there.
     */
    Rectangle[] captureSidePanelBounds(Client client)
    {
        final Rectangle container = visibleBounds(
            client.getWidget(sideContainerId)
        );
        final Rectangle background = visibleBounds(
            client.getWidget(sideBackgroundId)
        );

        if (container == null && background == null)
        {
            return new Rectangle[0];
        }

        if (container == null)
        {
            return new Rectangle[] { new Rectangle(background) };
        }

        if (background == null)
        {
            return new Rectangle[] { new Rectangle(container) };
        }

        return new Rectangle[]
        {
            new Rectangle(container),
            new Rectangle(background)
        };
    }

    private static Rectangle visibleBounds(Widget widget)
    {
        if (
            widget == null
                || widget.isHidden()
                || widget.getWidth() <= 0
                || widget.getHeight() <= 0
        )
        {
            return null;
        }

        final Rectangle bounds = widget.getBounds();
        return bounds == null || bounds.isEmpty() ? null : bounds;
    }

    static LayoutSpec forRoot(int rootId)
    {
        return rootId == MODERN.rootId ? MODERN : null;
    }

    static boolean isValidTab(int tabIndex)
    {
        return tabIndex >= 0 && tabIndex < TABS.length;
    }
}

package com.freddy.customgametabs;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.widgets.Widget;

/**
 * Thin adapter around RuneScape's own Resizable Modern tab state.
 *
 * Custom Game Tabs deliberately does not own side-panel lifetime anymore.
 * RuneScape decides when the panel opens, closes, is replaced by Bank/Shop/
 * storage interfaces, and what happens when those interfaces go away. We only
 * observe TOPLEVEL_PANEL for highlighting and reuse each native stone's OnOp
 * listener for direct left-click activation.
 */
@Singleton
final class NativeTabController
{
    private final Client client;

    /* Read by overlay rendering; writes happen on the client thread. */
    private volatile int displayedTab = -1;
    private volatile String[] tabNames = fallbackTabNames();

    @Inject
    NativeTabController(Client client)
    {
        this.client = client;
    }

    void startUp()
    {
        refreshDisplayedTab();
    }

    void shutDown()
    {
        displayedTab = -1;
        tabNames = fallbackTabNames();
    }

    void onGameStateChanged(GameState gameState)
    {
        if (gameState == GameState.LOGGED_IN)
        {
            refreshDisplayedTab();
        }
        else
        {
            displayedTab = -1;
            tabNames = fallbackTabNames();
        }
    }

    void onTopLevelRebuilt()
    {
        refreshDisplayedTab();
    }

    void onTopLevelPanelChanged()
    {
        refreshDisplayedTab();
    }

    void onPostClientTick()
    {
        if (client.getGameState() == GameState.LOGGED_IN)
        {
            refreshDisplayedTab();
        }
    }

    boolean isTabActive(int tabIndex)
    {
        return displayedTab == tabIndex;
    }

    String getTabName(int tabIndex)
    {
        if (!LayoutSpec.isValidTab(tabIndex))
        {
            return "";
        }

        final String[] names = tabNames;
        final String name = names[tabIndex];

        return name == null || name.isBlank()
            ? LayoutSpec.TABS[tabIndex].getName()
            : name;
    }

    void activateTab(int tabIndex)
    {
        activateTabOperation(tabIndex, 1);
    }

    void activateTabOperation(int tabIndex, int op)
    {
        final LayoutSpec layout = LayoutSpec.forRoot(
            client.getTopLevelInterfaceId()
        );

        if (
            layout == null
                || !LayoutSpec.isValidTab(tabIndex)
                || op < 1
        )
        {
            return;
        }

        /*
         * Left-click is an overlay click, not a RuneScape widget click, so reuse
         * the backing STONE's real listener. Right-click menu operations do not
         * come through here; NativeTabMenuBridge leaves them as genuine CC_OP
         * entries so RuneScape executes their full native widget-action path.
         */
        invokeNativeTabListener(layout, tabIndex, op);
    }

    private void refreshDisplayedTab()
    {
        final LayoutSpec layout = LayoutSpec.forRoot(
            client.getTopLevelInterfaceId()
        );

        if (layout == null)
        {
            displayedTab = -1;
            tabNames = fallbackTabNames();
            return;
        }

        refreshTabNames(layout);

        final int selectedTab = client.getVarcIntValue(
            VarClientID.TOPLEVEL_PANEL
        );

        if (!LayoutSpec.isValidTab(selectedTab))
        {
            displayedTab = -1;
            return;
        }

        /*
         * Logout is its own top-level tab. Every other normal tab is active
         * only while RuneScape's normal side panel is actually visible.
         */
        displayedTab = selectedTab == LayoutSpec.LOGOUT_TAB
            ? selectedTab
            : layout.isSidePanelOpen(client)
                ? selectedTab
                : -1;
    }

    private void refreshTabNames(LayoutSpec layout)
    {
        final String[] refreshed = fallbackTabNames();

        for (int tabIndex = 0; tabIndex < refreshed.length; tabIndex++)
        {
            final Widget stone = client.getWidget(
                layout.getStoneId(tabIndex)
            );

            if (stone == null)
            {
                continue;
            }

            final String[] actions = stone.getActions();
            if (
                actions != null
                    && actions.length > 0
                    && actions[0] != null
                    && !actions[0].isBlank()
            )
            {
                refreshed[tabIndex] = actions[0];
            }
        }

        tabNames = refreshed;
    }

    private boolean invokeNativeTabListener(
        LayoutSpec layout,
        int tabIndex,
        int op
    )
    {
        final Widget source = client.getWidget(
            layout.getStoneId(tabIndex)
        );
        if (source == null)
        {
            return false;
        }

        final Object[] onOpListener = source.getOnOpListener();
        if (onOpListener == null || onOpListener.length == 0)
        {
            return false;
        }

        client.createScriptEventBuilder(onOpListener)
            .setSource(source)
            .setOp(op)
            .build()
            .run();
        return true;
    }

    private static String[] fallbackTabNames()
    {
        final String[] names = new String[LayoutSpec.TABS.length];

        for (int index = 0; index < names.length; index++)
        {
            names[index] = LayoutSpec.TABS[index].getName();
        }

        return names;
    }
}

package com.freddy.customgametabs;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.EventBus;

/**
 * Projects the real Resizable Modern tab widget's menu semantics onto the
 * freely-positioned custom button.
 *
 * The native STONE remains the source of truth for action labels, operation
 * numbers, widget behavior, and component identity. Replaying MenuEntryAdded
 * while the entry still carries CC_OP identity lets RuneLite's MenuManager
 * attach any WidgetMenuOption registered for that STONE (for example the
 * Spellbook plugin's Magic-tab options) without depending on that plugin.
 */
@Singleton
final class NativeTabMenuBridge
{
    private final Client client;
    private final EventBus eventBus;

    @Inject
    NativeTabMenuBridge(
        Client client,
        EventBus eventBus
    )
    {
        this.client = client;
        this.eventBus = eventBus;
    }

    void prepareMenu(int tabIndex, boolean ownsSurface)
    {
        if (
            client.getGameState() != GameState.LOGGED_IN
                || client.isMenuOpen()
                || !ownsSurface
        )
        {
            return;
        }

        final Menu menu = client.getMenu();

        /* A real UI control occludes scene/NPC/object actions underneath it. */
        keepOnlyCancel(menu);

        if (!LayoutSpec.isValidTab(tabIndex))
        {
            ensureCancel(menu);
            return;
        }

        final LayoutSpec layout = LayoutSpec.forRoot(
            client.getTopLevelInterfaceId()
        );
        if (layout == null)
        {
            ensureCancel(menu);
            return;
        }

        final Widget stone = client.getWidget(layout.getStoneId(tabIndex));
        if (stone == null)
        {
            ensureCancel(menu);
            return;
        }

        buildNativeOperations(menu, stone);
        ensureCancel(menu);
    }

    private void buildNativeOperations(
        Menu menu,
        Widget stone
    )
    {
        final String[] actions = stone.getActions();
        if (actions == null)
        {
            return;
        }

        /*
         * The menu is displayed in reverse insertion order, so recreate widget
         * ops from the highest slot down to op 1.
         */
        for (int actionIndex = actions.length - 1;
             actionIndex >= 0;
             actionIndex--)
        {
            final String action = actions[actionIndex];
            if (action == null || action.isBlank())
            {
                continue;
            }

            final int op = actionIndex + 1;
            final MenuEntry entry = menu.createMenuEntry(-1)
                .setOption(action)
                .setTarget("")
                .setType(nativeActionType(op))
                .setIdentifier(op)
                /*
                 * These are static top-level widgets. Native CC_OP menu entries
                 * use child/index -1 and the full component id in param1.
                 */
                .setParam0(-1)
                .setParam1(stone.getId());

            /*
             * Creating a CC_OP-shaped entry is not enough for RuneLite-managed
             * widget options: MenuManager attaches those from MenuEntryAdded.
             * Dispatch the event with the real native component id and leave the
             * base entry as CC_OP afterward. That lets RuneScape execute the
             * complete native operation when the user selects it.
             */
            eventBus.post(new MenuEntryAdded(entry));
        }
    }

    private static MenuAction nativeActionType(int op)
    {
        return op <= 5
            ? MenuAction.CC_OP
            : MenuAction.CC_OP_LOW_PRIORITY;
    }

    private static void keepOnlyCancel(Menu menu)
    {
        final MenuEntry[] entries = menu.getMenuEntries();
        if (entries == null)
        {
            return;
        }

        for (MenuEntry entry : entries)
        {
            if (entry.getType() != MenuAction.CANCEL)
            {
                menu.removeMenuEntry(entry);
            }
        }
    }

    private static void ensureCancel(Menu menu)
    {
        final MenuEntry[] entries = menu.getMenuEntries();
        if (entries != null)
        {
            for (MenuEntry entry : entries)
            {
                if (entry.getType() == MenuAction.CANCEL)
                {
                    return;
                }
            }
        }

        menu.createMenuEntry(0)
            .setOption("Cancel")
            .setTarget("")
            .setType(MenuAction.CANCEL)
            .setIdentifier(0)
            .setParam0(0)
            .setParam1(0);
    }
}

package com.freddy.customgametabs;

import java.util.LinkedHashMap;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;

/**
 * Hides the original Resizable Modern tab presentation while leaving the real
 * widgets otherwise untouched.
 *
 * The native STONE widgets are backing authorities for Custom Game Tabs: their
 * actions, sub-ops, listeners, click configuration, and component identity are
 * intentionally preserved. Hidden state alone is enough to remove the original
 * rail from normal rendering/hit-testing without rewriting native semantics.
 */
final class NativeTabPresentation
{
    private final Client client;
    private final Map<Integer, CapturedWidgetState> originalStates =
        new LinkedHashMap<>();
    private LayoutSpec hiddenLayout;

    @Inject
    NativeTabPresentation(Client client)
    {
        this.client = client;
    }

    void update()
    {
        final LayoutSpec active = LayoutSpec.forRoot(
            client.getTopLevelInterfaceId()
        );

        if (active == null)
        {
            restoreAll();
            return;
        }

        if (hiddenLayout != active)
        {
            restoreAll();
            hiddenLayout = active;
        }

        for (int id : active.getRailLayerIds())
        {
            hide(id);
        }

        for (int id : active.getBackgroundIds())
        {
            hide(id);
        }

        /*
         * Hide the visible native controls too, but do not alter any of their
         * interaction/listener/action fields. The custom UI reads those fields
         * while the native widget remains in RuneScape's expected hierarchy.
         */
        for (int index = 0; index < LayoutSpec.TABS.length; index++)
        {
            hide(active.getStoneId(index));
            hide(active.getIconId(index));
        }
    }

    void restoreAll()
    {
        for (Map.Entry<Integer, CapturedWidgetState> entry :
            originalStates.entrySet())
        {
            final Widget current = client.getWidget(entry.getKey());
            final CapturedWidgetState captured = entry.getValue();

            /* Never restore stale state onto a replacement Widget instance. */
            if (current != null && current == captured.widget)
            {
                if (current.isSelfHidden() != captured.hidden)
                {
                    current.setHidden(captured.hidden);
                }
            }
        }

        originalStates.clear();
        hiddenLayout = null;
    }

    private void hide(int componentId)
    {
        final Widget widget = client.getWidget(componentId);
        if (widget == null)
        {
            return;
        }

        final CapturedWidgetState existing = originalStates.get(componentId);
        if (existing == null || existing.widget != widget)
        {
            originalStates.put(
                componentId,
                new CapturedWidgetState(widget, widget.isSelfHidden())
            );
        }

        if (!widget.isSelfHidden())
        {
            widget.setHidden(true);
        }
    }

    private static final class CapturedWidgetState
    {
        private final Widget widget;
        private final boolean hidden;

        private CapturedWidgetState(Widget widget, boolean hidden)
        {
            this.widget = widget;
            this.hidden = hidden;
        }
    }
}

